              "{\"headline\":\"China's central bank denies it's devaluing country's currency to counter tariffs\",\"dateCreated\":\"2019-08-05T12:29:02+0000\",\"datePublished\":\"2019-08-05T12:29:02+0000\",\"dateModified\":\"2019-08-05T15:39:27+0000\",\"author\":{\"name\":\"Yun Li\"},\"creator\":[\"Yun Li\"],\"publisher\":{\"name\":\"CNBC\",\"foundingDate\":\"1989-04-17\",\"sameAs\":[\"https://www.facebook.com/cnbc\",\"https://www.instagram.com/cnbc\",\"https://www.linkedin.com/company/cnbc\",\"https://twitter.com/cnbc\",\"https://en.wikipedia.org/wiki/CNBC\",\"https://www.youtube.com/cnbc\"]},\"articleSection\":\"Markets\",\"keywords\":[\"cnbc\",\"Articles\",\"Morgan Stanley Market Vectors Renminbi USD\",\"Breaking News: Markets\",\"Breaking News: Investing\",\"Breaking News: Business\",\"Investment strategy\",\"Wall Street\",\"Stock markets\",\"Markets\",\"U.S. Markets\",\"stocks\",\"Finance\",\"Investing\",\"source:tagname:CNBC US Source\"],\"video\":{\"description\":\"Jonathan Golub, Credit Suisse chief U.S. equity strategist, and Mark Vitner, Wells Fargo managing director and senior economist, join \\\"Squawk on the Street\\\" to discuss the market sell-off following China's devaluation of the yuan.\",\"duration\":\"PT5M42S\",\"name\":\"Unclear whether devaluation is China's 'counterpunch', says strategist\",\"thumbnailURL\":\"https://image.cnbcfm.com/api/v1/image/105953970-1559877543841gettyimages-961816202.jpeg?v=1625799954\",\"uploadDate\":\"2019-08-05T14:34:01+0000\"}}"
